        import pulumi_incident as incident

        # Look up a user to page. Escalation path targets can also be schedules or
        # Slack/Teams channels; see the `type` attribute on each target.
        on_call = incident.get_user(email="on-call@example.com")
        # A last resort path, which the path below hands over to out of hours.
        fallback = incident.EscalationPath("fallback",
            name="Fallback",
            path=[{
                "type": "level",
                "level": {
                    "targets": [{
                        "type": "user",
                        "id": on_call.id,
                        "urgency": "high",
                    }],
                    "timeToAckSeconds": 300,
                },
            }])
        # The same escalation path as the incident_escalation_path example, written as a
        # flat map of sequences: if in working hours, page with high urgency; otherwise
        # page with low urgency.
        urgent_support = incident.EscalationPath("urgent_support",
            name="Urgent support",
            start="main",
            sequences={
                "main": {
                    "nodes": [{
                        "id": "start",
                        "branch": {
                            "if_": {
                                "working_hours_active": "UK",
                            },
                            "then": "in_hours",
                            "else_": "out_of_hours",
                        },
                    }],
                },
                "in_hours": {
                    "nodes": [
                        {
                            "level": {
                                "targets": [{
                                    "type": "user",
                                    "id": on_call.id,
                                    "urgency": "high",
                                }],
                                "time_to_ack_seconds": 300,
                            },
                        },
                        {
                            "delay": {
                                "delay_seconds": 120,
                            },
                        },
                        {
                            "loop": {
                                "back_to": "start",
                                "times": 3,
                            },
                        },
                    ],
                },
                "out_of_hours": {
                    "nodes": [
                        {
                            "level": {
                                "targets": [{
                                    "type": "user",
                                    "id": on_call.id,
                                    "urgency": "low",
                                }],
                                "time_to_ack_seconds": 300,
                            },
                        },
                        {
                            "escalation_path": {
                                "escalation_path_id": fallback.id,
                            },
                        },
                    ],
                },
            },
            working_hours=[{
                "id": "UK",
                "name": "UK",
                "timezone": "Europe/London",
                "weekday_intervals": [{
                    "weekday": "monday",
                    "start_time": "09:00",
                    "end_time": "17:00",
                }],
            }])
